CREATE MASKING POLICY governance.email_mask AS (val STRING) RETURNS STRING ->
  CASE WHEN IS_ROLE_IN_SESSION('PII_READER') THEN val
       ELSE '***MASKED***' END;

ALTER TABLE crm.customers MODIFY COLUMN email
  SET MASKING POLICY governance.email_mask;

CREATE ROW ACCESS POLICY governance.region_rap AS (region STRING) RETURNS BOOLEAN ->
  EXISTS (SELECT 1 FROM governance.role_regions r
          WHERE r.role_name = CURRENT_ROLE() AND r.region = region);

ALTER TABLE sales.orders ADD ROW ACCESS POLICY governance.region_rap ON (region);

DELETE FROM lake.crm.customers WHERE customer_id = 42;
-- check rewrite options so files carrying deletes are really rewritten
CALL lake.system.rewrite_data_files(table => 'crm.customers');
CALL lake.system.expire_snapshots(
  table => 'crm.customers',
  older_than => TIMESTAMP '2026-11-10 00:00:00',
  retain_last => 1);
